import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, existsSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import test from 'node:test';

// Empty valid ASAR generated by @electron/asar.createPackage(). No app source,
// credentials, running process or real installation is touched by this test.
const archive = Buffer.from('BAAAABQAAAAQAAAADAAAAHsiZmlsZXMiOnt9fQ==', 'base64');
const helper = fileURLToPath(new URL('../lib/restart-desktop.js', import.meta.url));
const runtime = process.env.DSH_ELECTRON_BIN || process.execPath;

test('restart helper moves a real ASAR archive before reporting success', () => {
  const root = mkdtempSync(join(tmpdir(), 'dsh-purge-restart-test-'));
  const asar = join(root, 'app.asar');
  try {
    writeFileSync(asar, archive);
    for (let attempt = 0; attempt < 2; attempt++) {
      const result = spawnSync(runtime, [helper], {
        env: { ...process.env, TMPDIR: root, TMP: root, TEMP: root,
          ELECTRON_RUN_AS_NODE: '1', DSH_PURGE_RESTART: JSON.stringify({ asar, respawn: false, pid: 0 }) },
        encoding: 'utf8', timeout: 10000,
      });
      assert.equal(result.status, 0, result.stderr || result.error?.message);
      assert.equal(existsSync(asar), false, 'helper must move the archive, not just exit successfully');
      assert.deepEqual(readFileSync(`${asar}.bak`), archive);
    }
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test('restart helper reports a failed handoff instead of treating a directory as absent', () => {
  const root = mkdtempSync(join(tmpdir(), 'dsh-purge-restart-test-'));
  const asar = join(root, 'app.asar');
  try {
    mkdirSync(asar);
    const result = spawnSync(runtime, [helper], {
      env: { ...process.env, TMPDIR: root, TMP: root, TEMP: root,
        ELECTRON_RUN_AS_NODE: '1', DSH_PURGE_RESTART: JSON.stringify({ asar, respawn: false, pid: 0 }) },
      encoding: 'utf8', timeout: 10000,
    });
    assert.equal(result.status, 1, result.stderr || result.error?.message);
    assert.equal(existsSync(asar), true);
    assert.equal(existsSync(`${asar}.bak`), false);
  } finally { rmSync(root, { recursive: true, force: true }); }
});
